/**
 * Represents the arguments for the `columnVisibilityChange` event.
 */
export class ColumnVisibilityChangeEvent {
    /**
     * Contains the columns whose visibility changes.
     */
    columns;
    /**
     * @hidden
     */
    constructor(columns) {
        this.columns = columns;
    }
}
